#!/usr/bin/env python3
"""Generates docs/passes.md from the pass definitions (ops/include/ops-mlir/*/Passes.td) and the named pipelines of Pipelines.cpp.

    scripts/gen_passes_doc.py            # writes docs/passes.md
"""
import os
import re
import sys

root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
tds = [("Analysis", "ops/include/ops-mlir/Analysis/Passes.td"), ("Transforms", "ops/include/ops-mlir/Transforms/Passes.td"),
       ("Conversion", "ops/include/ops-mlir/Conversion/Passes.td")]

out = ["# Passes and pipelines", "",
       "Generated by `scripts/gen_passes_doc.py` from the TableGen definitions of the passes and the registry of `ops/lib/Pipelines/Pipelines.cpp`.",
       "Every pass is available in `ops-opt` under its name (`ops-opt file.mlir -<pass>`); the pipelines are also named pipelines of `ops-opt`", ""]

pipeline_text = open(os.path.join(root, "ops/lib/Pipelines/Pipelines.cpp")).read()
out += ["## Pipelines (`opdsl::PipelineRegistry`, used by the runtime and by `ops-opt -<pipeline>=\"options\"`)", "",
        "| pipeline | what it does | options |", "|---|---|---|"]
for m in re.finditer(r'registry\.add\(\{"([\w-]+)",\s*"([^"]*)",\s*\{(.*?)\},\s*build\w+\}\);', pipeline_text, re.S):
    name, doc, opts = m.group(1), m.group(2), m.group(3)
    options = ["`%s` (%s): %s" % (o.group(1), o.group(2), o.group(3)) for o in re.finditer(r'\{"([\w-]+)",\s*"([^"]*)",\s*"([^"]*)"\}', opts)]
    out.append("| `%s` | %s | %s |" % (name, doc, "<br>".join(options) if options else "none"))
out.append("")

for title, path in tds:
    p = os.path.join(root, path)
    if not os.path.exists(p):
        continue
    text = open(p).read()
    out += ["## %s passes" % title, ""]
    for m in re.finditer(r'def (\w+) : Pass<"([\w-]+)"(?:, "([^"]*)")?>\s*\{(.*?)\n\}', text, re.S):
        cls, name, anchor, body = m.groups()
        summary = re.search(r'let summary = "([^"]*)"', body)
        desc = re.search(r'let description = \[\{(.*?)\}\];', body, re.S)
        options = re.findall(r'Option<"(\w+)",\s*"([\w-]+)",\s*"([^"]*)",\s*/\*default=\*/"?([^,"\\]*(?:\\"[^,]*?\\")?)"?,\s*"([^"]*)"', body)
        out.append("### `%s`" % name)
        out.append("")
        if summary:
            out.append("*%s.*" % summary.group(1).rstrip("."))
            out.append("")
        if anchor:
            out.append("Runs on `%s`." % anchor.replace("::mlir::", ""))
            out.append("")
        if desc:
            lines = [l.strip() for l in desc.group(1).strip().splitlines()]
            out.append(" ".join(l for l in lines if l))
            out.append("")
        if options:
            out.append("Options: " + "; ".join("`%s` (%s, default %s): %s" % (o[1], o[2], o[3].replace("\\", "").strip() or "\"\"", o[4]) for o in options))
            out.append("")

open(os.path.join(root, "docs/passes.md"), "w").write("\n".join(out) + "\n")
print("docs/passes.md: %d lines" % len(out))
